<script setup lang="ts">
import { computed, ref, watch } from "vue"; import { dashboardApi } from "../api/ops"; import type { DashboardOverview } from "../types"; import EChart from "../components/EChart.vue";
const rangeDays=ref(7); const departmentId=ref(""); const data=ref<DashboardOverview|null>(null); const loading=ref(false); async function load(){loading.value=true;try{data.value=await dashboardApi.overview(rangeDays.value,departmentId.value)}finally{loading.value=false}} watch([rangeDays,departmentId],load,{immediate:true});
const tokenOption=computed(()=>({tooltip:{trigger:"axis"},xAxis:{type:"category",data:data.value?.token_trend.map(i=>i.label)||[]},yAxis:{type:"value"},series:[{type:"line",smooth:true,areaStyle:{},data:data.value?.token_trend.map(i=>i.value)||[]}]})); const latencyOption=computed(()=>({tooltip:{trigger:"axis"},xAxis:{type:"category",data:data.value?.latency_trend.map(i=>i.label)||[]},yAxis:{type:"value",name:"ms"},series:[{type:"line",smooth:true,data:data.value?.latency_trend.map(i=>i.value)||[]}]}));
</script><template><el-space direction="vertical" size="large" fill><el-card class="page-card" header="运营数据看板"><template #header><div class="card-header"><span>运营数据看板</span><el-space><el-select v-model="rangeDays" style="width:130px"><el-option :value="7" label="最近 7 天"/><el-option :value="14" label="最近 14 天"/><el-option :value="30" label="最近 30 天"/></el-select><el-input v-model="departmentId" placeholder="部门 ID" clearable style="width:160px"/><el-button @click="load">刷新</el-button></el-space></div></template><el-row :gutter="16"><el-col :span="4"><el-statistic title="访问量 PV" :value="data?.pv||0"/></el-col><el-col :span="4"><el-statistic title="独立用户 UV" :value="data?.uv||0"/></el-col><el-col :span="4"><el-statistic title="知识总数" :value="data?.knowledge_count||0"/></el-col><el-col :span="4"><el-statistic title="FAQ 命中率" :value="(data?.faq_hit_rate||0)*100" suffix="%"/></el-col><el-col :span="4"><el-statistic title="知识覆盖率" :value="(data?.coverage_rate||0)*100" suffix="%"/></el-col><el-col :span="4"><el-statistic title="平均响应" :value="data?.avg_latency_ms||0" suffix="ms"/></el-col></el-row></el-card><el-row :gutter="16"><el-col :span="12"><el-card header="Token 使用趋势"><EChart :option="tokenOption"/></el-card></el-col><el-col :span="12"><el-card header="响应时长趋势"><EChart :option="latencyOption"/></el-card></el-col></el-row><el-row :gutter="16"><el-col :span="12"><el-card header="高频问题 TOP"><el-table :data="data?.top_questions||[]"><el-table-column prop="label" label="问题"/><el-table-column prop="value" label="次数" width="90"/></el-table></el-card></el-col><el-col :span="12"><el-card header="热门知识 TOP"><el-table :data="data?.hot_knowledge||[]"><el-table-column prop="label" label="知识 ID"/><el-table-column prop="value" label="引用次数" width="90"/></el-table></el-card></el-col></el-row></el-space></template>
